// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;
        try c.deposit{value: amount}() {} catch { return; }
        uint afterDepositC = address(c).balance;
        uint afterDepositThis = address(this).balance;
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint finalC = address(c).balance;
        uint finalThis = address(this).balance;
        assertTrue(afterDepositC == beforeC + amount
            && afterDepositThis == beforeThis - amount
            && (
                // If withdrawAll reverted: balances unchanged from afterDeposit
                (reverted && finalC == afterDepositC && finalThis == afterDepositThis)
                ||
                // If withdrawAll succeeded: this contract should have regained the amount and c decreased by amount
                (!reverted && finalC + amount == afterDepositC && finalThis == afterDepositThis + amount)
            ));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
